package com.delivery.platform.payments.infrastructure;import com.delivery.platform.payments.application.PaymentProvider;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.util.UUID;@Component public class SimulatedPaymentProvider implements PaymentProvider{public String code(){return"SIMULATED";}public Result process(String ref,BigDecimal amount,String currency){boolean ok=ref==null||!ref.toUpperCase().contains("DECLINE");return ok?new Result(true,"sim_"+UUID.randomUUID(),"txn_"+UUID.randomUUID(),null,null):new Result(false,null,"txn_"+UUID.randomUUID(),"CARD_DECLINED","Pago rechazado por el simulador");}}
